import { getMostRecentSubscription } from "./subscription-helpers";

const checkValidSubscription = (mentee_subscription: any) => {
  if (!mentee_subscription || !mentee_subscription.pricing_plan) {
    return false;
  }
  const subscription = getMostRecentSubscription(mentee_subscription.subscriptions);
  if (mentee_subscription.pricing_plan.user_type === "paid") {
    return true;
  } else if (mentee_subscription.pricing_plan.user_type === "trial") {
    if (subscription.cancelledOn) {
      return false;
    }
    return true;
  }
  return false;
};

export default checkValidSubscription;
