import axios from 'axios';
import { firebaseAuth } from '../firebase/firebase.config';

// *******************************
// *** CREATING AXIOS INSTANCE ***
// *******************************


const commonAxiosInstance = axios.create({
  // baseURL: 'https://common-api.preplaced.dev/',
  baseURL: import.meta.env.VITE_PUBLIC_COMMON_API_URL,
});

commonAxiosInstance.defaults.headers.post['Content-Type'] = '*';
commonAxiosInstance.defaults.headers.post['Access-Control-Allow-Origin'] = '*';

const axiosInstance = axios.create({
  // baseURL: 'https://dashboard-api.preplaced.dev/',
  baseURL: import.meta.env.VITE_PREPLACED_DASHBOARD_API_URL,
});

axiosInstance.defaults.headers.post['Content-Type'] = '*';
axiosInstance.defaults.headers.post['Access-Control-Allow-Origin'] = '*';

const aibackendAxiosInstance = axios.create({
  baseURL: import.meta.env.VITE_PREPLACED_BACKEND_AI_URL,
});

aibackendAxiosInstance.defaults.headers.post['Content-Type'] = '*';
aibackendAxiosInstance.defaults.headers.post['Access-Control-Allow-Origin'] = '*';

// ************************
// *** DRIVER FUNCTIONS ***
// ************************

// For getting Authentication header (accessToken) for API calls
const authHeader = async (requestParams: any) => {
  let accessToken = '';

  // For getting access token on the client side
  if (typeof window !== 'undefined' && firebaseAuth.currentUser) {
    accessToken = await firebaseAuth.currentUser.getIdToken();
  } else if (requestParams && requestParams.authHeader) {
    accessToken = requestParams.authHeader;
  } else {
    const authToken = await chrome.storage.local.get("mentorAIUserAuthToken")
    accessToken = authToken.mentorAIUserAuthToken
  }
  return `Bearer ${accessToken}`;
};

// Set requestType as mentors in params
const getRequestParams = (requestParams: any, useRequestType: boolean = true) => {
  let params;
  if (useRequestType) {
    if (!requestParams) {
      params = {
        requestType: 'mentors',
      };
    } else {
      params = {
        requestType: 'mentors',
        ...requestParams,
      };
    }
  } else {
    params = requestParams
  }
  return params;
};

// *************************
// *** API CALL HANDLERS ***
// *************************

// Dashboard APIs get handler
const handleGet = async (url: any, requestParams: any) => {
  try {
    const params = getRequestParams(requestParams);
    const resp: any = await axiosInstance({
      method: 'GET',
      url,
      params,
      headers: {
        Authorization: await authHeader(requestParams),
      },
    });

    if (resp.status === 200) {
      const { data } = resp;

      return {
        status: resp.status,
        data,
        headers: resp.headers,
        url: resp.url,
      };
    }

    throw new Error(resp.statusText);
  } catch (err) {
    const errorMessage = (err as any).message ? (err as any).message : '';
    return Promise.reject(errorMessage);
  }
};

// Dashboard APIs post handler
const handlePost = async (url: any, requestData: any, requestParams?: any, useParams?: boolean, requestHeaders?: any, baseURL?: string) => {
  try {
    const params = getRequestParams(requestParams);
    const resp = await axiosInstance({
      method: 'POST',
      url,
      baseURL,
      headers: {
        Authorization: await authHeader(requestParams),
        ...requestHeaders
      },
      data: requestData,
      params: useParams ? params : undefined,
    });
    return resp.data;
  } catch (err) {
    console.log("err in handlePost", err);
    const errorMessage = (err as any).message ? (err as any).message : '';
    return Promise.reject(err);
  }
};

