// AI Backend APIs post handler
const handleAibackendPost = async (url: any, requestData: any, requestParams: any, requestHeaders?: any) => {
  requestHeaders = requestHeaders || {}
  try {
    const params = requestParams;

    const resp: any = await aibackendAxiosInstance({
      method: 'POST',
      url,
      headers: {
        Authorization: await authHeader(requestParams),
        "Content-Type": "application/json",
        ...requestHeaders
      },
      data: JSON.stringify(requestData),
      params,
    });

    if (resp.status === 200) {
      const { data } = resp;
      return {
        status: resp.status,
        data,
        headers: resp.headers,
        url: resp.url,
      };
    }
    return resp;

    // throw new Error(resp.statusText)
  } catch (err) {
    return Promise.reject(err);
  }
};


// Axios Does not support streaming response type, so using fetch instead
const handleAibackendStreamingPost = async (url: any, requestData: any, requestParams: any, requestHeaders?: any) => {
  requestHeaders = requestHeaders || {}
  try {
    const response = await fetch(
      `${import.meta.env.VITE_PREPLACED_BACKEND_AI_URL}${url}${requestParams ? `?${new URLSearchParams(requestParams).toString()}` : ''}`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": await authHeader(requestParams),
          ...requestHeaders
        },
        body: JSON.stringify(requestData),
      }
    )
    if (!response.ok) {
      // This will cause the promise to reject and .catch to run
      throw new Error(`Something went wrong! Please wait a moment and try again. If the issue persists, please contact support.`)
    }
    return response
  } catch (err) {
    return Promise.reject(err);
  }
};

