
export type UserType = 'free' | 'trial' | 'paid';
export type TrialDuration = '7' | '30';
export type PlanStatus = 'active' | 'cancelled' | 'expired';
export type TriggerPeriod = 'none' | 'before' | 'during' | 'last_day';

export interface UserStatus {
  userType: UserType;
  isTrial: boolean;
  isPaid: boolean;
  isFree: boolean;
  isCancelled: boolean;
  isExpired: boolean;
  isActive: boolean;
  trialDuration?: TrialDuration;
  daysRemaining: number;
  triggerPeriod: TriggerPeriod;
  isInTriggerPeriod: boolean;
}

/**
 * Calculate days between current date and target date
 */
export const calculateDaysRemaining = (targetDateStr: string): number => {
  if (!targetDateStr) return 0;

  let target: any = new Date(targetDateStr);
  if (`${target}`.includes("Invalid")) {
    target = new Date(targetDateStr?.split('T')?.[0]);
  }

  const now = new Date();

  const nowUTC = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
  const targetUTC = new Date(Date.UTC(target.getFullYear(), target.getMonth(), target.getDate()));

  const diffMs = targetUTC.getTime() - nowUTC.getTime();
  const days = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  return Math.max(0, days);
};

export const sortSubscriptionsByCreated = (subscriptions: any[]): any[] => {
  if (!subscriptions || !Array.isArray(subscriptions)) {
    return [];
  }
  return [...subscriptions].sort((a, b) => {
    const dateA = new Date(a.created);
    const dateB = new Date(b.created);
    return dateB.getTime() - dateA.getTime(); // Newest first
  });
};

export const getMostRecentSubscription = (subscriptions: any[]): any | null => {
  const sortedSubscriptions = sortSubscriptionsByCreated(subscriptions);
  return sortedSubscriptions.find(sub => sub.status === "Active") || sortedSubscriptions[0] || null;
};

/**
 * Check if user is on a trial plan
 */
export const isTrialPlan = (menteeSubscription: any): boolean => {
  if (!menteeSubscription || !menteeSubscription.pricing_plan) {
    return false
  }
  const mostRecentSubscription = getMostRecentSubscription(menteeSubscription.subscriptions);
  if (menteeSubscription.pricing_plan.user_type === "trial" && !mostRecentSubscription?.cancelledOn) {
    return true;
  }
  return false;
};

/**
 * Check if user is on a paid (non-trial) plan
 */
export const isPaidPlan = (menteeSubscription: any): boolean => {
  if (!menteeSubscription || !menteeSubscription.pricing_plan) {
    return false
  }
  if (menteeSubscription.pricing_plan.user_type === "paid") {
    return true;
  }
  return false;
};

/**
 * Get trial duration (7 or 30 days)
 */
export const getTrialDuration = (menteeSubscriptionDetails: any): TrialDuration | null => {
  if (!menteeSubscriptionDetails) return null;
  if (menteeSubscriptionDetails?.subscriptionTrialDays === 7) {
    return "7";
  } else if (menteeSubscriptionDetails?.subscriptionTrialDays === 30) {
    return "30";
  } else {
    return null;
  }
};

/**
 * Check if user has cancelled their plan
 */
export const isPlanCancelled = (menteeSubscriptionDetails: any): boolean => {
  if (!menteeSubscriptionDetails) return false;
  return menteeSubscriptionDetails?.status === "Active" && !!menteeSubscriptionDetails?.cancelledOn && menteeSubscriptionDetails?.pricing_plan?.user_type !== "trial";
};

/**
 * Check if plan is expired
 */
export const isPlanExpired = (menteeSubscriptionDetails: any): boolean => {
  if (!menteeSubscriptionDetails) return false;

  return menteeSubscriptionDetails?.status === "Expired";
};

/**
 * Check if plan is active
 */
export const isPlanActive = (menteeSubscriptionDetails: any): boolean => {
  if (!menteeSubscriptionDetails) return false;

  return menteeSubscriptionDetails?.status === "Active";
};

/**
 * Check if user is a paid user (has valid subscription)
 */
export const isUserPaid = (menteeSubscription: any): boolean => {
  if (!menteeSubscription || !menteeSubscription.pricing_plan) {
    return false
  }

  if (menteeSubscription.pricing_plan.user_type === "paid") {
    return true;
  }

  return false;
};

/**
 * Determine if user is in trigger period
 */
export const isInTriggerPeriod = (menteeSubscriptionDetails: any, daysRemaining: number, menteeSubscription: any): boolean => {
  if (!menteeSubscriptionDetails || !isPlanCancelled(menteeSubscriptionDetails)) return false;

  const trialDuration = getTrialDuration(menteeSubscriptionDetails);

  if (trialDuration === "7") {
    return daysRemaining <= 5;
  } else if (trialDuration === "30" || isPaidPlan(menteeSubscription)) {
    return daysRemaining <= 7;
  }

  return false;
};

/**
 * Determine trigger period type
 */
export const getTriggerPeriod = (menteeSubscriptionDetails: any, daysRemaining: number, menteeSubscription: any): TriggerPeriod => {
  if (!isPlanCancelled(menteeSubscriptionDetails)) return 'none';

  if (daysRemaining <= 1) return 'last_day';
  if (isInTriggerPeriod(menteeSubscriptionDetails, daysRemaining, menteeSubscription)) return 'during';

  return 'before';
};

/**
 * Get comprehensive user status
 */
export const getUserStatus = (menteeSubscription: any): UserStatus => {
  const menteeSubscriptionDetails = menteeSubscription?.subscriptions?.find((subscription: any) => subscription.status === "Active") || menteeSubscription?.subscriptions?.[0];

  // Determine user type
  let userType: UserType = 'free';
  if (isTrialPlan(menteeSubscription)) {
    userType = 'trial';
  } else if (isPaidPlan(menteeSubscription)) {
    userType = 'paid';
  }

  // Check if user is on trial
  const isTrial = isTrialPlan(menteeSubscription);

  // Check if user is paid (non-trial)
  const isPaid = isPaidPlan(menteeSubscription);

  // Check if user is free
  const isFree = !isTrial && !isPaid;

  // Check if plan is cancelled
  const isCancelled = isPlanCancelled(menteeSubscriptionDetails);

  // Check if plan is expired
  const isExpired = isPlanExpired(menteeSubscriptionDetails);

  // Check if plan is active
  const isActive = isPlanActive(menteeSubscriptionDetails);

  // Get trial duration
  const trialDuration = getTrialDuration(menteeSubscriptionDetails);

  // Calculate days remaining
  const daysRemaining = calculateDaysRemaining(menteeSubscriptionDetails?.actualExpirationDate || menteeSubscriptionDetails?.nextRenewalDate);

  // Determine trigger period
  const triggerPeriod = getTriggerPeriod(menteeSubscriptionDetails, daysRemaining, menteeSubscription);

  // Check if in trigger period
  const isInTriggerPeriodValue = isInTriggerPeriod(menteeSubscriptionDetails, daysRemaining, menteeSubscription);

  return {
    userType,
    isTrial,
    isPaid,
    isFree,
    isCancelled,
    isExpired,
    isActive,
    trialDuration: trialDuration || undefined,
    daysRemaining,
    triggerPeriod,
    isInTriggerPeriod: isInTriggerPeriodValue
  };
};