export type Currency = "INR" | "USD"

const getCurrency = (): Currency => {
  try {
    const region = Intl.DateTimeFormat().resolvedOptions().timeZone;
    if (!(region === 'Asia/Calcutta' || region === 'Asia/Kolkata')) {
      return "USD";
    }
  } catch (e) {
    console.error(e);
  }

  return "INR";
};

export const getFormattedPriceWithSymbol = (price: number, type: 'int' | 'float' = 'int') => {
  const currency = getCurrency();

  if (currency === 'USD') {
    if (type === 'float') return `$${price.toFixed(1).toLocaleString()}`;
    return `$${Math.floor(price).toLocaleString('en-US')}`;
  }
  if (type === 'float') return `₹${price.toFixed().toLocaleString()}`;
  return `₹${Math.floor(price).toLocaleString('en-IN')}`;
};

export default getCurrency;