import { handleAibackendGet } from "../../core/Axios"

export const mentorAiSubscriptionGetCall = async (mentee_id: string, mentorai_id: string, refetch: boolean = false) => {
  const { menteeSubscription: menteeSubscriptionFromLocalStorage } = await chrome.storage.local.get("menteeSubscription")

  if (refetch === false && menteeSubscriptionFromLocalStorage && menteeSubscriptionFromLocalStorage.lastFetchDateTime && new Date(menteeSubscriptionFromLocalStorage.lastFetchDateTime).getTime() + 1000 * 60 * 60 * 1 > new Date().getTime()) {
    return { mentee_subscription: menteeSubscriptionFromLocalStorage }
  }

  const response = await handleAibackendGet(`/mentorai/subscriptions/fetch_subscriptions`, {
    mentee_id: mentee_id,
    mentorai_id: mentorai_id
  })

  if (response && response.data) {
    await chrome.storage.local.set({ menteeSubscription: { ...response.data, lastFetchDateTime: new Date().toISOString() } })
    return { mentee_subscription: response.data }
  }

  return { mentee_subscription: null }
}